        {
            "Not directly. But two weeks ago, she stopped coming home for dinner. I could hear her on the phone, arguing with someone. She used words like 'forgery' and 'original documents'. I didn't understand, but I understood her voice. She was scared.",
            "Priya's work is always dangerous, Mr. Mehra. She fights for people who have no one else. She told me, 'Maa, if I can prove the land belongs to them, no one can touch them.' She was so hopeful. And then, suddenly, she wasn't.",
            "An inspector came. A woman. She looked around for ten minutes, asked me a few questions, and left. She said Priya probably went to visit a friend. But Priya's phone is here. Her wallet is here. What kind of person leaves without their phone?",
        };
        dlgAsked = new bool[3];

        dlgSpeaker = "KAMALA KAPOOR";
        dlgText = "Have you found anything?";
        var ask = VO("kamala_ask");
        if (ask != null) kamala.Say(ask);
        yield return W(ask != null ? ask.length + 0.3f : 1.5f);

        while (true)
        {
            dlgOptions = menu;
            dlgText = dlgText == null || dlgText.Length == 0 ? "Is there anything else you want to ask me?" : dlgText;
            int choice = -1;
            skipAll = false;
        skipAll = false;
            yield return null;
            while (choice < 0)
            {
                var kb = Keyboard.current;
                if (kb != null)
                {
                    if (kb.digit1Key.wasPressedThisFrame) choice = 0;
                    else if (kb.digit2Key.wasPressedThisFrame) choice = 1;
                    else if (kb.digit3Key.wasPressedThisFrame) choice = 2;
                    else if (kb.digit4Key.wasPressedThisFrame) choice = 3;
                }
                yield return null;
            }
            sfx.PlayOneShot(clickClip, 0.5f);
            dlgOptions = null;
            if (choice == 3)
            {
                dlgText = "Please, Mr. Mehra. Find my daughter.";
                var bye = VO("kamala_bye");
                if (bye != null) kamala.Say(bye);
                yield return W(bye != null ? bye.length + 0.6f : 2.5f);
                break;
            }
            dlgAsked[choice] = true;
            dlgText = replies[choice];
            var rc = VO(files[choice]);
            if (rc != null) kamala.Say(rc);
            yield return null;
            // wait for the line to finish or for the player to press E / Space
            while (true)
            {
                var kb = Keyboard.current;
                bool pressed = kb != null && (kb.eKey.wasPressedThisFrame || kb.spaceKey.wasPressedThisFrame);
                if (pressed || skipAll) { kamala.Silence(); break; }
                if (!kamala.IsTalking) { yield return W(0.4f); break; }
                yield return null;
            }
            dlgText = "";
            var more = VO("kamala_more");
            dlgText = "Is there anything else you want to ask me?";
            if (more != null) kamala.Say(more);
            yield return W(more != null ? more.length + 0.2f : 1f);
        }

        dlgSpeaker = null; dlgText = null; dlgOptions = null;
        dlgDone = true;
        SaveSystem.Data.dlgDone = true; SaveSystem.Save();
        PriyaRoomPlayer.Locked = false;
        phase = Phase.Explore;
        lastProgressTime = Time.time;
        AutoFocus.FocusOn = null;
        Toast("Mrs. Kapoor heads back down the stairs.", 3.5f);
        thoughtUntil = 0;
        yield return kamala.WalkTo(KamalaExit, 1.6f);
        if (kamala != null) { Destroy(kamala.gameObject); kamala = null; }
    }

    const int TotalClues = 9;                 // every clue is compulsory
    bool allCluesTriggered;

    /// <summary>All nine clues are in (and Mrs. Kapoor has been spoken to): the case moves on automatically.</summary>
    IEnumerator AllCluesFound()
    {
        allCluesTriggered = true;
        moveOnOffered = true;
        SaveSystem.Data.moveOnOffered = true; SaveSystem.Save();
        PriyaRoomPlayer.Locked = true;
        phase = Phase.Dialogue;
        objective = ""; prompt = ""; journalOpen = false;
        thoughtUntil = 0;
        sfx.PlayOneShot(dingClip, 0.7f);
        Toast("All 9 clues found. The picture is complete...", 3.5f);
        yield return new WaitForSeconds(2.6f);
        yield return MoveAhead();
    }

    // ============================================================ MOVE ON?
    IEnumerator MoveOnChoice()
    {
        moveOnOffered = true;
        SaveSystem.Data.moveOnOffered = true; SaveSystem.Save();
        phase = Phase.Dialogue;
        PriyaRoomPlayer.Locked = true;
        objective = ""; prompt = ""; journalOpen = false;
        thoughtUntil = 0;
        sfx.PlayOneShot(dingClip, 0.6f);

        dlgAsked = null; dlgPlain = true;
        dlgSpeaker = "CASE STATUS   -   " + foundCount + " of 9 clues found";
        dlgText = "You have enough evidence to follow a lead. The phone number from the sticky note points to a chai stall in the market.\n\nMove ahead now, or keep searching Priya's room for more clues?";
        dlgOptions = new[] { "Move ahead  -  follow the lead to the market", "Keep searching  -  find more clues first" };
        int choice = -1;
        skipAll = false;
        yield return null;
        while (choice < 0)
        {
            var kb = Keyboard.current;
            if (kb != null)
            {
                if (kb.digit1Key.wasPressedThisFrame) choice = 0;
                else if (kb.digit2Key.wasPressedThisFrame) choice = 1;
            }
            yield return null;
        }
        sfx.PlayOneShot(clickClip, 0.5f);
        dlgSpeaker = null; dlgText = null; dlgOptions = null; dlgPlain = false;

        if (choice == 0)
        {
            yield return MoveAhead();
        }
        else
        {
            moveOnDeclined = true;
            SaveSystem.Data.moveOnDeclined = true; SaveSystem.Save();
            PriyaRoomPlayer.Locked = false;
            phase = Phase.Explore;
            lastProgressTime = Time.time;
            Toast("Take your time. Press N whenever you're ready to move ahead.", 6f);
        }
    }

    IEnumerator MoveAhead()
    {
        phase = Phase.Dialogue;                 // pauses the explore logic while we wait
        PriyaRoomPlayer.Locked = false;
        journalOpen = false;
        while (!PlayerClearOfDoor())
        {
            Toast("Step away from the door...", 1f);
            yield return null;
        }
        yield return HookSequence();
    }

    // ================================================================= HOOK
    IEnumerator HookSequence()
    {
        phase = Phase.Hook;
        objective = "";
        bellEnabled = false;

        StartCoroutine(RampAmbience(ambience.volume, 0.12f, 2.5f));
        sub = "The sounds of the city seem to quiet."; subUntil = Time.time + 3.5f; subSkippable = false;
        yield return new WaitForSeconds(3f);

        for (int i = 0; i < 7; i++)
        {
            hall3d.PlayOneShot(stepClip, 0.5f + i * 0.08f);
            if (i == 3)
            {
                sfx.PlayOneShot(creakClip, 0.4f);
                StartCoroutine(SwingDoor(0f, 1.5f));
            }
            yield return new WaitForSeconds(i < 5 ? 0.85f : 1.1f);
        }

        lightStrip = GameObject.CreatePrimitive(PrimitiveType.Cube);
        lightStrip.name = "UnderDoorLight";
        lightStrip.transform.SetParent(builder.Root, false);
        lightStrip.transform.localPosition = new Vector3(-2f, 0.006f, -2.42f);
        lightStrip.transform.localScale = new Vector3(0.92f, 0.004f, 0.07f);
        Destroy(lightStrip.GetComponent<Collider>());
        lightStrip.GetComponent<Renderer>().sharedMaterial = UnlitMat(new Color(1f, 0.85f, 0.5f));

        var shadow = GameObject.CreatePrimitive(PrimitiveType.Cube);
        shadow.transform.SetParent(builder.Root, false);
        shadow.transform.localScale = new Vector3(0.16f, 0.006f, 0.08f);
        Destroy(shadow.GetComponent<Collider>());
        shadow.GetComponent<Renderer>().sharedMaterial = UnlitMat(new Color(0.02f, 0.01f, 0.01f));
        for (float t = 0; t < 2.6f; t += Time.deltaTime)
        {
            shadow.transform.localPosition = new Vector3(Mathf.Lerp(-2.4f, -1.55f, t / 2.6f), 0.009f, -2.42f);
            yield return null;
        }
        Destroy(shadow);
        hall3d.PlayOneShot(stepClip, 0.4f);

        sub = "Someone is standing outside the door."; subUntil = Time.time + 4f; subSkippable = false;
        Toast("Look at the door and press E to open it.", 6f);
        objective = "Open the door";
        phase = Phase.DoorReady;
    }

    static Material UnlitMat(Color c)
    {
        var sh = Shader.Find("Universal Render Pipeline/Unlit");
        if (sh == null) sh = Shader.Find("Unlit/Color");
        var m = new Material(sh);
        m.color = c;
        if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", c);
        return m;
    }

    IEnumerator SwingDoor(float toAngle, float dur)
    {
        var h = builder.DoorHinge;
        float from = h.localEulerAngles.y;
        if (from > 180f) from -= 360f;
        for (float t = 0; t < dur; t += Time.deltaTime)
        {
            float k = Mathf.SmoothStep(0, 1, t / dur);
            h.localRotation = Quaternion.Euler(0, Mathf.Lerp(from, toAngle, k), 0);
            yield return null;
        }
        h.localRotation = Quaternion.Euler(0, toAngle, 0);
    }

    IEnumerator OpenDoor()
    {
        phase = Phase.NoteReady;
        objective = "";
        prompt = "";
        sfx.PlayOneShot(creakClip, 0.5f);
        if (lightStrip) Destroy(lightStrip);
        yield return SwingDoor(-100f, 1.2f);
        builder.HookNote.SetActive(true);
        sub = "The stairwell is empty. The footsteps are gone. But on the floor, just outside the door..."; subUntil = Time.time + 5f; subSkippable = false;
        Toast("Look at the paper on the floor and press E.", 6f);
        objective = "Pick up the note";
    }

    // =============================================================== FINALE
    IEnumerator Finale()
    {
        phase = Phase.Ending;
        PriyaRoomPlayer.Locked = true;
        objective = "";
        journalOpen = false;
        ShowThought("A FOLDED NOTE", "\"Stop looking. She doesn't want to be found.  - A friend\"", 6f);
        yield return Say("arjun_note", "ARJUN (reading)", "Stop looking. She doesn't want to be found. A friend.");
        thoughtUntil = 0;
        yield return Say("arjun_handwriting", "ARJUN", "The handwriting matches the sticky note from under the keyboard. Whoever left this knows Priya. Someone who has been inside this apartment.");
        yield return Say("arjun_closing", "ARJUN (V.O.)", "Someone is watching me. And they know Priya. The question is, are they protecting her, or protecting themselves?");
        fadeSpeed = 0.5f; fadeTarget = 1f;
        StartCoroutine(RampAmbience(ambience.volume, 0f, 3f));
        yield return new WaitForSeconds(2.5f);
        SaveSystem.CompleteAct(1);
        StartActII(false);
    }

    void StartActII(bool resume)
    {
        if (!resume) SaveSystem.ResetAct(2);
        var root = new GameObject("ActII_Market");
        builder.ExtraRoot = root;
        player.transform.SetParent(root.transform, true);   // keep the player when the room is switched off
        builder.Root.gameObject.SetActive(false);
        var market = root.AddComponent<MarketStory>();
        market.builder = builder;
        market.player = player;
        market.resume = resume;
        enabled = false;                                      // Act I logic and UI stop here
    }

