    const int SR = 44100;

    AudioClip MakeAmbience()
    {
        int n = SR * 8, tail = 4000;
        float[] g = new float[n + tail];
        var r = new System.Random(5);
        float lp1 = 0, lp2 = 0, lp3 = 0;
        for (int i = 0; i < g.Length; i++)
        {
            float w = (float)(r.NextDouble() * 2 - 1);
            lp1 += (w - lp1) * 0.02f;
            lp2 += (lp1 - lp2) * 0.06f;
            lp3 += (w - lp3) * 0.25f;
            float t = i / (float)SR;
            float fan = 0.5f + 0.5f * Mathf.Sin(2f * Mathf.PI * 2.5f * t);
            g[i] = lp2 * 5f * (0.7f + 0.3f * fan) + lp3 * 0.05f * fan + 0.012f * Mathf.Sin(2f * Mathf.PI * 50f * t);
        }
        float[] d = new float[n];
        for (int k = 0; k < n; k++)
        {
            if (k < tail) { float a = k / (float)tail; d[k] = g[k] * a + g[n + k] * (1f - a); }
            else d[k] = g[k];
        }
        Normalize(d, 0.45f);
        var c = AudioClip.Create("ambience", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    AudioClip MakeBell()
    {
        int n = SR * 5;
        float[] d = new float[n];
        float[] f = { 392f, 784f, 1082f, 2117f, 3490f };
        float[] a = { 1f, 0.6f, 0.4f, 0.22f, 0.12f };
        float[] dec = { 0.9f, 1.3f, 1.7f, 2.6f, 3.6f };
        for (int i = 0; i < n; i++)
        {
            float t = i / (float)SR, s = 0;
            for (int p = 0; p < f.Length; p++) s += a[p] * Mathf.Exp(-t * dec[p]) * Mathf.Sin(2f * Mathf.PI * f[p] * t);
            d[i] = s * Mathf.Clamp01(t * 200f);
        }
        Normalize(d, 0.6f);
        var c = AudioClip.Create("bell", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    AudioClip MakeStep()
    {
        int n = SR / 3;
        float[] d = new float[n];
        var r = new System.Random(9);
        for (int i = 0; i < n; i++)
        {
            float t = i / (float)SR;
            d[i] = Mathf.Sin(2f * Mathf.PI * 75f * t) * Mathf.Exp(-t * 22f) + (float)(r.NextDouble() * 2 - 1) * Mathf.Exp(-t * 45f) * 0.35f;
        }
        Normalize(d, 0.8f);
        var c = AudioClip.Create("step", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    AudioClip MakeClick()
    {
        int n = SR / 10;
        float[] d = new float[n];
        for (int i = 0; i < n; i++)
        {
            float t = i / (float)SR;
            d[i] = Mathf.Sin(2f * Mathf.PI * 880f * t) * Mathf.Exp(-t * 55f) * 0.5f;
        }
        var c = AudioClip.Create("click", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    AudioClip MakeDing()
    {
        int n = SR * 6 / 10;
        float[] d = new float[n];
        for (int i = 0; i < n; i++)
        {
            float t = i / (float)SR;
            float a = Mathf.Sin(2f * Mathf.PI * 784f * t) * Mathf.Exp(-t * 7f);
            float b = t > 0.09f ? Mathf.Sin(2f * Mathf.PI * 1175f * (t - 0.09f)) * Mathf.Exp(-(t - 0.09f) * 6f) : 0f;
            d[i] = (a + b) * 0.35f;
        }
        var c = AudioClip.Create("ding", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    AudioClip MakeCreak()
    {
        int n = SR * 12 / 10;
        float[] d = new float[n];
        float ph = 0;
        for (int i = 0; i < n; i++)
        {
            float t = i / (float)SR;
            float f = 110f + 70f * Mathf.Sin(t * 5f) + 40f * t;
            ph += 2f * Mathf.PI * f / SR;
            float saw = (ph / (2f * Mathf.PI)) % 1f * 2f - 1f;
            d[i] = saw * Mathf.Sin(Mathf.PI * t / 1.2f) * 0.3f;
        }
        var c = AudioClip.Create("creak", n, 1, SR, false);
        c.SetData(d, 0);
        return c;
    }

    static void Normalize(float[] d, float peak)
    {
        float m = 0.0001f;
        for (int i = 0; i < d.Length; i++) m = Mathf.Max(m, Mathf.Abs(d[i]));
        float k = peak / m;
        for (int i = 0; i < d.Length; i++) d[i] *= k;
    }

